// Schedule kinds understood by the `pulumi stack schedule` commands.
const (
	scheduleKindRaw   = "raw"
	scheduleKindDrift = "drift"
	scheduleKindTTL   = "ttl"
)

// scheduleSummary is a flattened, human-readable summary of a scheduled action. It is
// also the JSON output shape used by the list and get commands.
type scheduleSummary struct {
	ID       string `json:"id"`
	Type     string `json:"type"`
	Settings string `json:"settings"`
	Schedule string `json:"schedule"`
	NextRun  string `json:"nextRun,omitempty"`
	LastRun  string `json:"lastRun,omitempty"`
	Created  string `json:"created,omitempty"`
}

// scheduleGetRenderFunc renders a single scheduled action.
type scheduleGetRenderFunc func(w io.Writer, schedule apitype.ScheduledAction) error

// scheduleListRenderFunc renders a list of scheduled actions.
type scheduleListRenderFunc func(w io.Writer, schedules []apitype.ScheduledAction) error

// scheduleDetails decodes the interesting parts of a scheduled action's definition.
type scheduleDetails struct {
	op                 apitype.PulumiOperation
	deleteAfterDestroy bool
	autoRemediate      bool
}

// decodeScheduleDetails extracts the operation and option flags from the schedule
// definition, tolerating an empty or malformed definition.
func decodeScheduleDetails(s apitype.ScheduledAction) scheduleDetails {
	var details scheduleDetails
	if len(s.Definition) == 0 {
		return details
	}
	var def apitype.ScheduledDeploymentDefinition
	if err := json.Unmarshal(s.Definition, &def); err != nil {
		return details
	}
	if def.Request == nil {
		return details
	}
	details.op = def.Request.Op
	if def.Request.Operation != nil && def.Request.Operation.Options != nil {
		details.deleteAfterDestroy = def.Request.Operation.Options.DeleteAfterDestroy
		details.autoRemediate = def.Request.Operation.Options.RemediateIfDriftDetected
	}
	return details
}

// inferScheduleKind determines the kind (raw/drift/ttl) of a scheduled action from its
// definition and timing fields.
func inferScheduleKind(s apitype.ScheduledAction) string {
	details := decodeScheduleDetails(s)
	switch {
	case details.op == apitype.Destroy && s.ScheduleOnce != "":
		return scheduleKindTTL
	case details.op == apitype.DetectDrift:
		return scheduleKindDrift
	default:
		return scheduleKindRaw
	}
}

// scheduleTimingString renders the human-readable schedule column for a scheduled action.
func scheduleTimingString(s apitype.ScheduledAction) string {
	switch {
	case s.ScheduleCron != "":
		return s.ScheduleCron
	case s.ScheduleOnce != "":
		return "Once"
	default:
		return ""
	}
}

// toScheduleSummary converts a scheduled action into its flattened summary.
func toScheduleSummary(s apitype.ScheduledAction) scheduleSummary {
	details := decodeScheduleDetails(s)
	summary := scheduleSummary{
		ID:       s.ID,
		Schedule: scheduleTimingString(s),
		NextRun:  s.NextExecution,
		Created:  s.Created,
	}
	if s.LastExecuted != nil {
		summary.LastRun = *s.LastExecuted
	}

	switch {
	case details.op == apitype.Destroy && s.ScheduleOnce != "":
		summary.Type = scheduleKindTTL
		summary.Schedule = "Once"
		if details.deleteAfterDestroy {
			summary.Settings = "destroy + delete stack"
		} else {
			summary.Settings = "destroy"
		}
	case details.op == apitype.DetectDrift:
		summary.Type = scheduleKindDrift
		summary.Settings = "detect"
	default:
		summary.Type = scheduleKindRaw
		summary.Settings = "pulumi " + string(details.op)
	}
	return summary
}

