func newStackScheduleListCmd() *cobra.Command {
	var (
		stack  string
		output string
		count  int
	)

	cmd := &cobra.Command{
		Hidden: true,
		Use:    "list",
		Short:  "List all scheduled actions configured for a stack",
		Long:   "[EXPERIMENTAL] List all scheduled actions configured for a stack.",
		RunE: func(cmd *cobra.Command, args []string) error {
			render, err := scheduleListRenderer(output)
			if err != nil {
				return err
			}
			return runStackScheduleList(
				cmd.Context(), cmd.OutOrStdout(), defaultStackScheduleListClientFactory, stack, count, render)
		},
	}

	constrictor.AttachArguments(cmd, constrictor.NoArgs)

	cmd.Flags().StringVarP(&stack, "stack", "s", "",
		"The name of the stack to operate on. Defaults to the current stack")
	cmd.Flags().StringVarP(&output, "output", "o", "default",
		"The output format: default (human-readable table) or json")
	cmd.Flags().IntVar(&count, "count", 0,
		"The maximum number of schedules to display (0 shows all)")

	return cmd
}

